        robot.move(Direction.RIGHT);     // to the packing tile
        robot.turn(Direction.DOWN);      // facing the bag
        robot.putInBag(Product.TOMATO);  // into the bag
        robot.move(Direction.LEFT);      // behind the screen
        robot.turn(Direction.DOWN);      // facing the register
        list.add(Product.TOMATO);        // note it down
    }
